import javax.swing.*;
import javax.swing.border.*;
import javax.swing.table.*;
import java.awt.*;
import java.sql.*;

/** JobConnect: simple functional college job portal. Java Swing + JDBC + SQLite. */
public class JobConnect extends JFrame {
    private static final Color NAVY=new Color(42,75,125), BLUE=new Color(55,110,185), BG=new Color(247,248,250), TEXT=new Color(48,55,65), MUTED=new Color(115,120,130);
    private String email, name, role;
    private JPanel main;
    private static final String DB="jdbc:sqlite:jobconnect.db";
    private Connection db() throws SQLException {return DriverManager.getConnection(DB);}
    public JobConnect(){super("JobConnect | Online Job Portal");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1080,720);setMinimumSize(new Dimension(850,570));setLocationRelativeTo(null);initDB();welcome();}
    private void initDB(){try(Connection c=db();Statement s=c.createStatement()){
        s.executeUpdate("CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL)");
        s.executeUpdate("CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,recruiter_email TEXT NOT NULL,title TEXT NOT NULL,company TEXT NOT NULL,location TEXT NOT NULL,description TEXT NOT NULL)");
        s.executeUpdate("CREATE TABLE IF NOT EXISTS applications(id INTEGER PRIMARY KEY AUTOINCREMENT,job_id INTEGER NOT NULL,candidate_email TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Pending',UNIQUE(job_id,candidate_email))");
    }catch(SQLException ex){error(ex.getMessage());}}
    private JPanel panel(){JPanel p=new JPanel();p.setBackground(BG);return p;}
    private JPanel white(){JPanel p=new JPanel();p.setBackground(Color.WHITE);p.setBorder(new CompoundBorder(new LineBorder(new Color(222,227,235)),new EmptyBorder(20,22,20,22)));return p;}
    private JLabel label(String s,int size,boolean bold){JLabel l=new JLabel(s);l.setFont(new Font("SansSerif",bold?Font.BOLD:Font.PLAIN,size));l.setForeground(bold?NAVY:TEXT);return l;}
    private JButton btn(String s){JButton b=new JButton(s);b.setFont(new Font("SansSerif",Font.BOLD,13));b.setBackground(BLUE);b.setForeground(Color.WHITE);b.setOpaque(true);b.setBorder(new EmptyBorder(10,17,10,17));b.setFocusPainted(false);b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));return b;}
    private JButton secondary(String s){JButton b=btn(s);b.setBackground(Color.WHITE);b.setForeground(NAVY);b.setBorder(new CompoundBorder(new LineBorder(new Color(208,218,232)),new EmptyBorder(9,16,9,16)));return b;}
    private JTextField input(){JTextField t=new JTextField(23);t.setFont(new Font("SansSerif",Font.PLAIN,14));t.setBorder(new CompoundBorder(new LineBorder(new Color(211,220,232)),new EmptyBorder(8,10,8,10)));return t;}
    private JPasswordField pass(){JPasswordField t=new JPasswordField(23);t.setFont(new Font("SansSerif",Font.PLAIN,14));t.setBorder(new CompoundBorder(new LineBorder(new Color(211,220,232)),new EmptyBorder(8,10,8,10)));return t;}
    private void show(JComponent p){setContentPane(p);revalidate();repaint();}
    private void error(String s){JOptionPane.showMessageDialog(this,s,"JobConnect",JOptionPane.ERROR_MESSAGE);}
    private void info(String s){JOptionPane.showMessageDialog(this,s,"JobConnect",JOptionPane.INFORMATION_MESSAGE);}
    private boolean confirm(String s){return JOptionPane.showConfirmDialog(this,s,"Confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
    private void addField(JPanel p,String title,JComponent c){p.add(label(title,12,true));p.add(Box.createVerticalStrut(5));c.setAlignmentX(Component.LEFT_ALIGNMENT);c.setMaximumSize(new Dimension(450,40));p.add(c);p.add(Box.createVerticalStrut(15));}
    private JPanel authCard(String title,String subtitle){JPanel p=white();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));p.add(label("JobConnect",27,true));p.add(Box.createVerticalStrut(7));p.add(label(title,21,true));p.add(Box.createVerticalStrut(5));p.add(label(subtitle,13,false));p.add(Box.createVerticalStrut(24));return p;}
    private void authShow(JPanel card){JPanel p=panel();p.setLayout(new GridBagLayout());p.add(card);show(p);}
    private void welcome(){email=name=role=null;JPanel c=authCard("Welcome to JobConnect","Find opportunities or hire talented candidates.");
        JButton login=btn("Login"),reg=secondary("Create Account");login.addActionListener(e->login());reg.addActionListener(e->register());
        c.add(login);c.add(Box.createVerticalStrut(12));c.add(reg);c.add(Box.createVerticalStrut(22));c.add(label("Demo accounts are listed in README.txt",12,false));authShow(c);
    }
    private void login(){JPanel c=authCard("Login","Enter your registered email and password.");JTextField mail=input();JPasswordField pwd=pass();JComboBox<String> type=new JComboBox<>(new String[]{"Candidate","Recruiter"});
        addField(c,"EMAIL",mail);addField(c,"PASSWORD",pwd);addField(c,"ACCOUNT TYPE",type);JButton go=btn("Login"),back=secondary("Back");
        go.addActionListener(e->{String m=mail.getText().trim().toLowerCase(),pw=new String(pwd.getPassword());try(Connection d=db();PreparedStatement s=d.prepareStatement("SELECT name,role FROM users WHERE lower(email)=? AND password=? AND role=?")){s.setString(1,m);s.setString(2,pw);s.setString(3,(String)type.getSelectedItem());try(ResultSet r=s.executeQuery()){if(r.next()){email=m;name=r.getString(1);role=r.getString(2);dashboard();}else error("Incorrect email, password, or account type.");}}catch(SQLException ex){error(ex.getMessage());}});
        back.addActionListener(e->welcome());c.add(go);c.add(Box.createVerticalStrut(10));c.add(back);authShow(c);
    }
    private void register(){JPanel c=authCard("Create Account","Register as a candidate or recruiter.");JTextField full=input(),mail=input();JPasswordField pwd=pass();JComboBox<String> type=new JComboBox<>(new String[]{"Candidate","Recruiter"});
        addField(c,"FULL NAME",full);addField(c,"EMAIL",mail);addField(c,"PASSWORD",pwd);addField(c,"ACCOUNT TYPE",type);JButton submit=btn("Submit / Create Account"),back=secondary("Back to Login");
        submit.addActionListener(e->{String n=full.getText().trim(),m=mail.getText().trim().toLowerCase(),pw=new String(pwd.getPassword());if(n.isEmpty()||!m.contains("@")||pw.length()<4){error("Enter your name, a valid email and a password of at least 4 characters.");return;}try(Connection d=db();PreparedStatement s=d.prepareStatement("INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)")){s.setString(1,n);s.setString(2,m);s.setString(3,pw);s.setString(4,(String)type.getSelectedItem());s.executeUpdate();info("Account created! Please log in.");login();}catch(SQLException ex){error("Could not create account. This email may already be registered.\n"+ex.getMessage());}});
        back.addActionListener(e->login());c.add(submit);c.add(Box.createVerticalStrut(10));c.add(back);authShow(c);
    }
    private void shell(String title,JComponent content){JPanel page=panel();page.setLayout(new BorderLayout());JPanel header=new JPanel(new BorderLayout());header.setBackground(Color.WHITE);header.setBorder(new EmptyBorder(15,25,15,25));header.add(label("JobConnect  /  "+title,20,true),BorderLayout.WEST);header.add(label(name+"  |  "+role,13,false),BorderLayout.EAST);page.add(header,BorderLayout.NORTH);
        JPanel nav=new JPanel();nav.setBackground(new Color(236,241,248));nav.setBorder(new EmptyBorder(20,12,20,12));nav.setLayout(new BoxLayout(nav,BoxLayout.Y_AXIS));nav.setPreferredSize(new Dimension(192,0));
        navButton(nav,"Dashboard",()->dashboard());if("Candidate".equals(role)){navButton(nav,"Browse Jobs",()->browseJobs(""));navButton(nav,"My Applications",()->candidateApps());}else{navButton(nav,"My Job Posts",()->myJobs());navButton(nav,"Post a Job",()->jobForm(-1));navButton(nav,"Applications",()->recruiterApps());}
        navButton(nav,"My Profile",()->profile());nav.add(Box.createVerticalGlue());navButton(nav,"Logout",()->welcome());page.add(nav,BorderLayout.WEST);
        JPanel holder=panel();holder.setLayout(new BorderLayout());holder.setBorder(new EmptyBorder(22,25,22,25));holder.add(content,BorderLayout.CENTER);page.add(holder,BorderLayout.CENTER);show(page);
    }
    private void navButton(JPanel p,String text,Runnable run){JButton b=secondary(text);b.setMaximumSize(new Dimension(165,43));b.setAlignmentX(Component.LEFT_ALIGNMENT);b.addActionListener(e->run.run());p.add(b);p.add(Box.createVerticalStrut(12));}
    private JPanel content(String title,String subtitle){JPanel p=panel();p.setLayout(new BorderLayout(0,18));JPanel head=panel();head.setLayout(new BoxLayout(head,BoxLayout.Y_AXIS));head.add(label(title,24,true));head.add(Box.createVerticalStrut(5));head.add(label(subtitle,13,false));p.add(head,BorderLayout.NORTH);return p;}
    private int count(String sql,String parameter){try(Connection c=db();PreparedStatement s=c.prepareStatement(sql)){if(parameter!=null)s.setString(1,parameter);try(ResultSet r=s.executeQuery()){return r.next()?r.getInt(1):0;}}catch(SQLException ex){error(ex.getMessage());return 0;}}
    private JPanel metric(String title,int n){JPanel p=white();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));p.add(label(title,13,false));p.add(Box.createVerticalStrut(12));p.add(label(String.valueOf(n),29,true));return p;}
    private void dashboard(){JPanel p=content("Welcome, "+name,"Your "+role.toLowerCase()+" dashboard. Select a feature from the left menu.");JPanel center=panel();center.setLayout(new BorderLayout(0,20));JPanel stats=new JPanel(new GridLayout(2,2,15,15));stats.setOpaque(false);
        stats.add(metric("Registered Candidates",count("SELECT COUNT(*) FROM users WHERE role='Candidate'",null)));stats.add(metric("Registered Recruiters",count("SELECT COUNT(*) FROM users WHERE role='Recruiter'",null)));
        stats.add(metric("Available Jobs",count("SELECT COUNT(*) FROM jobs",null)));stats.add(metric("Recruiter".equals(role)?"Applications Received":"My Applications",count("Recruiter".equals(role)?"SELECT COUNT(*) FROM applications a JOIN jobs j ON j.id=a.job_id WHERE j.recruiter_email=?":"SELECT COUNT(*) FROM applications WHERE candidate_email=?",email)));
        center.add(stats,BorderLayout.NORTH);JPanel actions=white();actions.setLayout(new FlowLayout(FlowLayout.LEFT,12,12));if("Candidate".equals(role)){JButton a=btn("Browse & Apply for Jobs"),b=secondary("Track My Applications");a.addActionListener(e->browseJobs(""));b.addActionListener(e->candidateApps());actions.add(a);actions.add(b);}else{JButton a=btn("Post New Job"),b=secondary("Manage My Jobs"),c=secondary("Review Applications");a.addActionListener(e->jobForm(-1));b.addActionListener(e->myJobs());c.addActionListener(e->recruiterApps());actions.add(a);actions.add(b);actions.add(c);}center.add(actions,BorderLayout.CENTER);p.add(center,BorderLayout.CENTER);shell("Dashboard",p);
    }
    private DefaultTableModel model(String... columns){return new DefaultTableModel(columns,0){public boolean isCellEditable(int r,int c){return false;}};}
    private JTable table(DefaultTableModel m){JTable t=new JTable(m);t.setFont(new Font("SansSerif",Font.PLAIN,13));t.setRowHeight(33);t.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);t.setSelectionBackground(new Color(218,231,250));t.setSelectionForeground(NAVY);t.setShowVerticalLines(false);t.getTableHeader().setFont(new Font("SansSerif",Font.BOLD,13));t.getTableHeader().setBackground(new Color(234,240,248));t.setAutoCreateRowSorter(true);return t;}
    private JPanel tableArea(JTable t){JPanel c=white();c.setLayout(new BorderLayout());c.add(new JScrollPane(t),BorderLayout.CENTER);return c;}
    private JPanel toolbar(){JPanel p=panel();p.setLayout(new FlowLayout(FlowLayout.LEFT,10,4));return p;}
    private int selectedId(JTable t){int row=t.getSelectedRow();if(row<0){error("Please select a row first.");return -1;}return Integer.parseInt(t.getValueAt(row,0).toString());}
    private void browseJobs(String filter){JPanel p=content("Browse Jobs","Search available jobs, inspect details, and submit applications.");DefaultTableModel m=model("ID","Job Title","Company","Location","Description");
        String sql="SELECT id,title,company,location,description FROM jobs WHERE lower(title) LIKE ? OR lower(company) LIKE ? OR lower(location) LIKE ? ORDER BY id DESC";
        try(Connection c=db();PreparedStatement s=c.prepareStatement(sql)){for(int i=1;i<=3;i++)s.setString(i,"%"+filter.toLowerCase()+"%");try(ResultSet r=s.executeQuery()){while(r.next())m.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)});}}catch(SQLException ex){error(ex.getMessage());}
        JTable t=table(m);JPanel center=tableArea(t);JPanel bar=toolbar();JTextField search=input();search.setText(filter);search.setColumns(19);JButton find=btn("Search"),all=secondary("Show All"),details=secondary("Job Details"),apply=btn("Apply"),mine=secondary("My Applications");find.addActionListener(e->browseJobs(search.getText().trim()));all.addActionListener(e->browseJobs(""));
        details.addActionListener(e->{int id=selectedId(t);if(id>=0){int row=t.getSelectedRow();JTextArea a=new JTextArea("Job: "+t.getValueAt(row,1)+"\nCompany: "+t.getValueAt(row,2)+"\nLocation: "+t.getValueAt(row,3)+"\n\n"+t.getValueAt(row,4));a.setEditable(false);a.setLineWrap(true);a.setWrapStyleWord(true);a.setRows(10);a.setColumns(40);JOptionPane.showMessageDialog(this,new JScrollPane(a),"Job Details",JOptionPane.INFORMATION_MESSAGE);}});
        apply.addActionListener(e->{int id=selectedId(t);if(id<0)return;try(Connection c=db();PreparedStatement s=c.prepareStatement("INSERT INTO applications(job_id,candidate_email,status) VALUES(?,?,'Pending')")){s.setInt(1,id);s.setString(2,email);s.executeUpdate();info("Application submitted successfully!");browseJobs(search.getText().trim());}catch(SQLException ex){error("Could not apply. You may already have applied for this job.");}});mine.addActionListener(e->candidateApps());
        bar.add(search);bar.add(find);bar.add(all);bar.add(details);bar.add(apply);bar.add(mine);center.add(bar,BorderLayout.SOUTH);p.add(center,BorderLayout.CENTER);shell("Browse Jobs",p);
    }
    private void candidateApps(){JPanel p=content("My Applications","Track each application or withdraw one that you no longer want.");DefaultTableModel m=model("Application ID","Job","Company","Location","Status");
        try(Connection c=db();PreparedStatement s=c.prepareStatement("SELECT a.id,j.title,j.company,j.location,a.status FROM applications a JOIN jobs j ON a.job_id=j.id WHERE a.candidate_email=? ORDER BY a.id DESC")){s.setString(1,email);try(ResultSet r=s.executeQuery()){while(r.next())m.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)});}}catch(SQLException ex){error(ex.getMessage());}
        JTable t=table(m);JPanel center=tableArea(t),bar=toolbar();JButton withdraw=btn("Withdraw Selected"),browse=secondary("Browse Jobs"),refresh=secondary("Refresh");withdraw.addActionListener(e->{int id=selectedId(t);if(id<0||!confirm("Withdraw this job application?"))return;try(Connection c=db();PreparedStatement s=c.prepareStatement("DELETE FROM applications WHERE id=? AND candidate_email=?")){s.setInt(1,id);s.setString(2,email);s.executeUpdate();candidateApps();}catch(SQLException ex){error(ex.getMessage());}});browse.addActionListener(e->browseJobs(""));refresh.addActionListener(e->candidateApps());bar.add(withdraw);bar.add(browse);bar.add(refresh);center.add(bar,BorderLayout.SOUTH);p.add(center,BorderLayout.CENTER);shell("My Applications",p);
    }
    private void myJobs(){JPanel p=content("My Job Posts","Edit or remove jobs you posted, or create a new vacancy.");DefaultTableModel m=model("ID","Job Title","Company","Location","Applications","Description");
        try(Connection c=db();PreparedStatement s=c.prepareStatement("SELECT j.id,j.title,j.company,j.location,(SELECT COUNT(*) FROM applications a WHERE a.job_id=j.id),j.description FROM jobs j WHERE j.recruiter_email=? ORDER BY j.id DESC")){s.setString(1,email);try(ResultSet r=s.executeQuery()){while(r.next())m.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getInt(5),r.getString(6)});}}catch(SQLException ex){error(ex.getMessage());}
        JTable t=table(m);JPanel center=tableArea(t),bar=toolbar();JButton post=btn("Post Job"),edit=secondary("Edit Selected"),delete=secondary("Delete Selected"),apps=secondary("View Applications");post.addActionListener(e->jobForm(-1));edit.addActionListener(e->{int id=selectedId(t);if(id>=0)jobForm(id);});delete.addActionListener(e->{int id=selectedId(t);if(id<0||!confirm("Delete this job and all applications for it?"))return;try(Connection c=db()){c.setAutoCommit(false);try(PreparedStatement a=c.prepareStatement("DELETE FROM applications WHERE job_id=?");PreparedStatement j=c.prepareStatement("DELETE FROM jobs WHERE id=? AND recruiter_email=?")){a.setInt(1,id);a.executeUpdate();j.setInt(1,id);j.setString(2,email);j.executeUpdate();c.commit();myJobs();}catch(SQLException ex){c.rollback();throw ex;}}catch(SQLException ex){error(ex.getMessage());}});apps.addActionListener(e->recruiterApps());bar.add(post);bar.add(edit);bar.add(delete);bar.add(apps);center.add(bar,BorderLayout.SOUTH);p.add(center,BorderLayout.CENTER);shell("My Job Posts",p);
    }
    private void jobForm(int id){String[] old={"","","",""};if(id>=0){try(Connection c=db();PreparedStatement s=c.prepareStatement("SELECT title,company,location,description FROM jobs WHERE id=? AND recruiter_email=?")){s.setInt(1,id);s.setString(2,email);try(ResultSet r=s.executeQuery()){if(!r.next()){error("Job not found.");return;}for(int i=0;i<4;i++)old[i]=r.getString(i+1);}}catch(SQLException ex){error(ex.getMessage());return;}}
        JPanel p=content(id<0?"Post a Job":"Edit Job","Provide complete details so candidates can find the opportunity.");JPanel c=white();c.setLayout(new BoxLayout(c,BoxLayout.Y_AXIS));JTextField title=input(),company=input(),location=input();title.setText(old[0]);company.setText(old[1]);location.setText(old[2]);JTextArea description=new JTextArea(old[3],6,35);description.setLineWrap(true);description.setWrapStyleWord(true);description.setFont(new Font("SansSerif",Font.PLAIN,14));JScrollPane scroll=new JScrollPane(description);scroll.setMaximumSize(new Dimension(450,150));scroll.setAlignmentX(Component.LEFT_ALIGNMENT);addField(c,"JOB TITLE",title);addField(c,"COMPANY",company);addField(c,"LOCATION",location);addField(c,"JOB DESCRIPTION",scroll);
        JButton save=btn(id<0?"Publish Job":"Save Changes"),back=secondary("Cancel");save.addActionListener(e->{String a=title.getText().trim(),b=company.getText().trim(),loc=location.getText().trim(),desc=description.getText().trim();if(a.isEmpty()||b.isEmpty()||loc.isEmpty()||desc.isEmpty()){error("Please fill in every field.");return;}String sql=id<0?"INSERT INTO jobs(recruiter_email,title,company,location,description) VALUES(?,?,?,?,?)":"UPDATE jobs SET title=?,company=?,location=?,description=? WHERE id=? AND recruiter_email=?";try(Connection d=db();PreparedStatement s=d.prepareStatement(sql)){if(id<0){s.setString(1,email);s.setString(2,a);s.setString(3,b);s.setString(4,loc);s.setString(5,desc);}else{s.setString(1,a);s.setString(2,b);s.setString(3,loc);s.setString(4,desc);s.setInt(5,id);s.setString(6,email);}s.executeUpdate();info(id<0?"Job published successfully.":"Job updated successfully.");myJobs();}catch(SQLException ex){error(ex.getMessage());}});back.addActionListener(e->myJobs());JPanel buttons=toolbar();buttons.add(save);buttons.add(back);c.add(buttons);JScrollPane wrapper=new JScrollPane(c);wrapper.setBorder(null);p.add(wrapper,BorderLayout.CENTER);shell(id<0?"Post Job":"Edit Job",p);
    }
    private void recruiterApps(){JPanel p=content("Received Applications","Review candidates who applied to your jobs and change their status.");DefaultTableModel m=model("Application ID","Job","Candidate Name","Candidate Email","Status");
        String sql="SELECT a.id,j.title,COALESCE(u.name,'Unknown'),a.candidate_email,a.status FROM applications a JOIN jobs j ON a.job_id=j.id LEFT JOIN users u ON u.email=a.candidate_email WHERE j.recruiter_email=? ORDER BY a.id DESC";
        try(Connection c=db();PreparedStatement s=c.prepareStatement(sql)){s.setString(1,email);try(ResultSet r=s.executeQuery()){while(r.next())m.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)});}}catch(SQLException ex){error(ex.getMessage());}
        JTable t=table(m);JPanel center=tableArea(t),bar=toolbar();JComboBox<String> status=new JComboBox<>(new String[]{"Pending","Shortlisted","Selected","Rejected"});JButton update=btn("Update Selected Status"),refresh=secondary("Refresh");update.addActionListener(e->{int id=selectedId(t);if(id<0)return;try(Connection c=db();PreparedStatement s=c.prepareStatement("UPDATE applications SET status=? WHERE id=? AND job_id IN (SELECT id FROM jobs WHERE recruiter_email=?)")){s.setString(1,(String)status.getSelectedItem());s.setInt(2,id);s.setString(3,email);if(s.executeUpdate()>0){info("Application status updated.");recruiterApps();}else error("Application not found.");}catch(SQLException ex){error(ex.getMessage());}});refresh.addActionListener(e->recruiterApps());bar.add(label("New status:",13,false));bar.add(status);bar.add(update);bar.add(refresh);center.add(bar,BorderLayout.SOUTH);p.add(center,BorderLayout.CENTER);shell("Applications",p);
    }
    private void profile(){JPanel p=content("My Profile","Update your display name and optionally change your password.");JPanel c=white();c.setLayout(new BoxLayout(c,BoxLayout.Y_AXIS));JTextField full=input();full.setText(name);JTextField mail=input();mail.setText(email);mail.setEditable(false);JPasswordField password=pass();addField(c,"FULL NAME",full);addField(c,"EMAIL (READ ONLY)",mail);addField(c,"NEW PASSWORD (LEAVE BLANK TO KEEP CURRENT)",password);c.add(label("Account type: "+role,13,false));c.add(Box.createVerticalStrut(18));JButton save=btn("Save Profile");save.addActionListener(e->{String n=full.getText().trim(),pw=new String(password.getPassword());if(n.isEmpty()||(!pw.isEmpty()&&pw.length()<4)){error("Name is required. New password must have at least 4 characters.");return;}try(Connection d=db();PreparedStatement s=d.prepareStatement("UPDATE users SET name=?,password=CASE WHEN ?='' THEN password ELSE ? END WHERE email=?")){s.setString(1,n);s.setString(2,pw);s.setString(3,pw);s.setString(4,email);s.executeUpdate();name=n;info("Profile saved.");profile();}catch(SQLException ex){error(ex.getMessage());}});c.add(save);p.add(c,BorderLayout.CENTER);shell("My Profile",p);
    }
    public static void main(String[] args){SwingUtilities.invokeLater(()->{try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());}catch(Exception ignored){}new JobConnect().setVisible(true);});}
}
